// Split approved actions to process individually
const approvedActions = $input.item.json.approved_actions || [];
const outputs = [];

for (const approval of approvedActions) {
  if (approval.approved) {
    outputs.push({
      json: {
        action_id: approval.action_id,
        action_type: approval.action_type || 'notes', // Default
        payload: approval.payload || {},
        session_id: $input.item.json.session_id
      }
    });
  }
}

return outputs;

// Simulate MCP Notes Handler
const payload = $input.item.json.payload;

return {
  json: {
    action_id: $input.item.json.action_id,
    action_type: 'notes',
    status: 'success',
    message: `Notes entry added: ${payload.entry_title}`,
    file: '/home/user/fees_explanations.md'
  }
};

// Simulate MCP Email Handler
const payload = $input.item.json.payload;
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

return {
  json: {
    action_id: $input.item.json.action_id,
